:root {
  --cream: #f2e8d5;
  --parchment: #e4d4b0;
  --ink: #2c1f0e;
  --ink-faded: #6b5033;
  --rust: #9b3a1a;
  --rust-light: #c4582a;
  --teal: #1d6a6a;
  --teal-light: #d4eaea;
  --gold: #b8892a;
  --divider: #c8b07a;
  --pip-off: #d6c49a;
  --white: #ffffff;
}

.log-card {
  background-color: var(--cream);
  border: 2px solid var(--divider);
  border-radius: 4px;
  width: 476px;
  max-width: 476px;
  padding: 0;
  overflow: hidden;
  font-size: 12px;
  color: var(--ink);
}

.log-header {
  background-color: var(--teal);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
  border-bottom: 3px solid var(--gold);
}

.header-left,
.header-right {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.header-right {
  align-items: flex-end;
}

.station-label,
.log-no-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--teal-light);
  text-transform: uppercase;
}

.station-name {
  font-size: 14px;
  font-weight: 700;
  color: var(--white);
  letter-spacing: 0.04em;
}

.log-no {
  font-size: 13px;
  font-weight: 700;
  color: var(--gold);
  letter-spacing: 0.06em;
}

.lighthouse-icon {
  font-size: 24px;
  margin: 0;
  line-height: 1;
}

.log-body {
  padding: 8px 12px;
}

.meta-row {
  display: flex;
  border: 1px solid var(--divider);
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 8px;
}

.meta-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 5px 4px;
  border-right: 1px solid var(--divider);
  background-color: var(--parchment);
  gap: 1px;
}

.meta-item:last-child {
  border-right: none;
}

.meta-label {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--ink-faded);
  text-transform: uppercase;
}

.meta-value {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink);
}

.log-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.log-entry {
  display: grid;
  grid-template-columns: 32px 8px 1fr;
  align-items: start;
  column-gap: 4px;
  background-color: var(--white);
  border: 1px solid var(--divider);
  border-radius: 3px;
  padding: 5px 7px;
}

.entry-time {
  font-size: 10px;
  font-weight: 700;
  color: var(--rust);
  letter-spacing: 0.04em;
  line-height: 1.4;
}

.entry-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--gold);
  margin-top: 3px;
  justify-self: center;
}

.entry-text {
  margin: 0;
  font-size: 10px;
  line-height: 1.4;
  color: var(--ink-faded);
}

.entry-text em {
  font-style: italic;
  color: var(--teal);
}

.log-footer {
  background-color: var(--parchment);
  border-top: 2px solid var(--divider);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 12px;
}

.condition-bar {
  display: flex;
  align-items: center;
  gap: 6px;
}

.cond-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--ink-faded);
  text-transform: uppercase;
}

.cond-pips {
  display: flex;
  gap: 3px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.pip {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  background-color: var(--pip-off);
  border: 1px solid var(--divider);
}

.pip.active {
  background-color: var(--rust-light);
  border-color: var(--rust);
}

.cond-desc {
  font-size: 10px;
  font-weight: 600;
  color: var(--ink);
}

.signature-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
  border-left: 1px solid var(--divider);
  padding-left: 12px;
}

.sig-line {
  font-size: 12px;
  font-weight: 700;
  font-style: italic;
  color: var(--ink);
  letter-spacing: 0.03em;
}

.sig-role {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--ink-faded);
  text-transform: uppercase;
}
